import{_ as t,o as i,c as o,a2 as a}from"./chunks/framework.x7b91k6X.js";const u=JSON.parse('{"title":"漫画 · 第 14 话 系统触点：Widget 与 App Intents","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.14-system-touchpoints.md","filePath":"comics/EP.14-system-touchpoints.md","lastUpdated":1792677465000}'),n={name:"comics/EP.14-system-touchpoints.md"};function r(s,e,d,l,p,c){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="漫画-·-第-14-话-系统触点-widget-与-app-intents" tabindex="-1">漫画 · 第 14 话 系统触点：Widget 与 App Intents <a class="header-anchor" href="#漫画-·-第-14-话-系统触点-widget-与-app-intents" aria-label="Permalink to &quot;漫画 · 第 14 话 系统触点：Widget 与 App Intents&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../14-system-touchpoints">14-system-touchpoints.md</a> ｜ 原画：<a href="./EP.14-system-touchpoints.svg">EP.14-system-touchpoints.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>斯威芙蒂</strong>：Widget 半天不刷新、喊 Siri 没反应、推送通知显示的是密文。App 孤立在系统之外，用户不打开就触达不了。</li><li><strong>Runtime 长老</strong>：教她用 WidgetKit、App Intents、通知扩展三大触点把 App 能力延伸到系统层面。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>App 的价值不只在打开时，更在用户不打开时也能提供服务。三大系统触点：①WidgetKit 用时间线机制在锁屏/桌面展示信息，有系统刷新预算；②App Intents 让 Siri 和快捷指令能调用 App 能力；③通知 Service 扩展在送达前解密切文，既保护隐私又展示可读内容。主 App 和扩展通过 App Group 共享数据。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><ul><li><strong>Widget 不刷新</strong>：以为像 App 一样想刷就刷，结果系统有刷新预算（每小时几次），频繁请求被节流；</li><li><strong>Siri 无响应</strong>：没有定义 App Intents，Siri 不知道你的 App 能做什么；</li><li><strong>通知是密文</strong>：服务端推送加密内容，直接显示用户看不懂，又不想在 App 内解密（延迟）。</li></ul><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>三大系统触点：</p><ul><li><strong>WidgetKit</strong>：不是实时刷新，而是用 <code>TimelineProvider</code> 预生成一批时间点的视图快照（<code>TimelineEntry</code>），系统按时间展示。刷新策略 <code>.atEnd</code>（时间线结束再请求下一批，最省预算）、<code>.after(date)</code>（指定时间刷新）、<code>.never</code>（静态不刷新）。</li><li><strong>App Intents</strong>：定义 <code>AppIntent</code> 协议的结构体，声明参数和执行方法，系统自动接入 Siri、快捷指令、聚焦搜索、Action Button。三角色：AppIntent（做什么）、AppEntity（操作对象）、AppEnum（枚举参数）。</li><li><strong>通知扩展</strong>：<code>UNNotificationServiceExtension</code> 在通知送达用户前拦截，解密 payload 中的密文，替换为明文再展示。30 秒超时，超时走原始内容。</li><li><strong>App Group</strong>：主 App 和扩展是独立进程，通过 <code>group.&lt;bundle-id&gt;</code> 共享 UserDefaults、文件容器、Keychain 项目。</li></ul><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><ol><li><strong>Widget 时间线策略</strong>：用 <code>.atEnd</code> 让系统在时间线末尾再请求下一批，避免频繁刷新耗尽预算；</li><li><strong>深链打通</strong>：<code>widgetURL</code> 或 <code>Link(destination:)</code> 让点击 Widget 跳转到 App 对应页面；</li><li><strong>通知解密</strong>：Service Extension 用共享的密钥（App Group Keychain）解密切文，展示明文标题。</li></ol><h2 id="runtime-长老划重点" tabindex="-1">Runtime 长老划重点 <a class="header-anchor" href="#runtime-长老划重点" aria-label="Permalink to &quot;Runtime 长老划重点&quot;">​</a></h2><ol><li>Widget 用 Timeline 预生成快照，刷新有系统预算，不要频繁请求。</li><li>App Intents 让 Siri/快捷指令调用 App 能力，App Group 共享数据给扩展。</li><li>通知 Service 扩展在送达前解密切文，保护隐私同时展示可读内容。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：Widget 为什么不能像 App 一样实时刷新数据？</p><p><strong>答</strong>：因为 Widget 运行在独立进程，系统为了省电和性能，对 Widget 的刷新有严格预算（每小时几次，具体由系统根据用户使用频率动态调整）。如果允许实时刷新，等于每个 Widget 都在后台常驻跑网络，电池和性能扛不住。所以 WidgetKit 设计成「时间线快照」模式：你一次性提供未来一段时间的数据快照，系统按时间展示，到时间线末尾再回调你请求下一批。要实时更新只能用 <code>WidgetCenter.shared.reloadAllTimelines()</code>，但要省着用。</p><h2 id="去实验室" tabindex="-1">去实验室 <a class="header-anchor" href="#去实验室" aria-label="Permalink to &quot;去实验室&quot;">​</a></h2><p>运行 <code>swift run SystemTouchpoints</code>，查看 <code>TimelinePolicy.swift</code>（刷新策略决策）、<code>WidgetDeepLink.swift</code>（深链往返）和 <code>NotificationEnvelope.swift</code>（通知解密降级）的实现；阅读第 14 章的 App Intents 三角色和 App Group 配置。</p><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>系统触点全覆盖了，可上线后崩溃率升高、用户反馈卡顿、灰度发布不知道该不该全量。第 15 话《运营闭环：可观测性与灰度》，让数据驱动运营决策。</p>',23)])])}const g=t(n,[["render",r]]);export{u as __pageData,g as default};
